const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.startsWith('Bearer ') && authHeader.slice(7);
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Forbidden' });
  }
}

// Apply to sensitive routes
app.get('/users', requireAuth, (req, res) => { ... });
```

---

### 🟠 Finding 3 — No Input Validation Middleware

**Severity: High | OWASP A03: Injection**

The app has no body parser and no input validation library configured. As routes are added (e.g., `POST /users`), there is no established pattern to validate or sanitize incoming data, making injection (SQLi, NoSQLi, XSS stored via API) likely as the app grows.

**Recommendation:**
```js
const express = require('express');
const { body, param, query, validationResult } = require('express-validator');

app.use(express.json({ limit: '10kb' })); // parse body + cap payload size

// Example: validated POST route
app.post('/users',
  body('name').isString().trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });
    // safe to proceed
  }
);
```

---

### 🟠 Finding 4 — Missing Security Headers

**Severity: High | OWASP A05: Security Misconfiguration**

Express, by default, sends an `X-Powered-By: Express` header (fingerprinting) and sets no protective headers (no CSP, no `X-Frame-Options`, no HSTS, etc.).

**Recommendation:**
```js
const helmet = require('helmet');

app.use(helmet()); // sets 14 security headers in one call
// Includes: CSP, HSTS, X-Frame-Options, X-Content-Type-Options, etc.

// Also explicitly remove the fingerprinting header
app.disable('x-powered-by');
```

---

### 🟠 Finding 5 — No Rate Limiting

**Severity: High | OWASP A04: Insecure Design**

There is no rate limiting on any endpoint. This makes the app trivially vulnerable to brute-force attacks and denial-of-service via request flooding.

**Recommendation:**
```js
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

app.use(limiter); // global limiter

// Stricter limiter for auth routes
const authLimiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 10 });
app.use('/login', authLimiter);
```

---

### 🟡 Finding 6 — No CORS Policy

**Severity: Medium | OWASP A05: Security Misconfiguration**

No CORS headers are configured. If this API is consumed by a browser client, the default behavior either blocks legitimate cross-origin requests or (if wildcard CORS is added carelessly) allows any origin to make credentialed requests.

**Recommendation:**
```js
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? [],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));
```

---

### 🟡 Finding 7 — No Centralized Error Handling

**Severity: Medium | OWASP A09: Security Logging and Monitoring Failures**

There is no error handling middleware. Unhandled promise rejections or thrown errors will either crash the process or cause Express to leak stack traces (file paths, library versions, internal logic) to clients in development mode.

**Recommendation:**
```js
// Place LAST, after all routes
app.use((err, req, res, next) => {
  // Log internally with full detail
  console.error({ err, path: req.path, method: req.method });

  // Respond externally with NO internal details
  const status = err.status ?? 500;
  res.status(status).json({
    error: status < 500 ? err.message : 'Internal server error',
  });
});

// Catch unhandled async errors (Node 15+)
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled rejection:', reason);
});
```

---

### 🟡 Finding 8 — No Request Logging / Audit Trail

**Severity: Medium | OWASP A09: Security Logging and Monitoring Failures**

There is no access logging. Without logs it is impossible to detect attacks, audit access to user data, or investigate incidents.

**Recommendation:**
```js
const morgan = require('morgan');

// Use 'combined' format in production for full Apache-style logs
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));
```

